import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ClientBoundControlSchemeSet{ControlScheme: 3}
PLAYER_RELATIVE = bytes.fromhex("03")

# generated by gophertunnel b8bd735:
# &packet.ClientBoundControlSchemeSet{ControlScheme: 4}
PLAYER_RELATIVE_STRAFE = bytes.fromhex("04")

GOLDENS = [
    pytest.param(
        v2225.ClientboundControlSchemeSetPacket(control_scheme=v2225.Scheme.PLAYER_RELATIVE),
        PLAYER_RELATIVE,
        id="player-relative",
    ),
    pytest.param(
        v2225.ClientboundControlSchemeSetPacket(control_scheme=v2225.Scheme.PLAYER_RELATIVE_STRAFE),
        PLAYER_RELATIVE_STRAFE,
        id="player-relative-strafe",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_clientbound_control_scheme_set_is_packet_327(version):
    assert version.packets[327] is version.ClientboundControlSchemeSetPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_control_scheme_set_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_control_scheme_set_decodes_from_its_golden(packet, golden):
    assert v2225.ClientboundControlSchemeSetPacket.from_bytes(golden) == packet


def test_decode_rejects_an_empty_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.ClientboundControlSchemeSetPacket.from_bytes(b"")
